const projectRoot = $env.PFA_PROJECT_ROOT;
const python = $env.PFA_PYTHON || 'python';
if (!projectRoot) {
  throw new Error('PFA_PROJECT_ROOT environment variable is not set on the n8n host. See docs/n8n-setup.md.');
}

function shQuote(value) {
  return `'${String(value).replace(/'/g, "'\\''")}'`;
}

const feedbackFile = $json['Feedback file path'];
const analysisQuery = $json['Analysis query'];
const contextFilesRaw = $json['Context file paths (comma-separated)'] || '';
const contextFiles = contextFilesRaw
  .split(',')
  .map((s) => s.trim())
  .filter(Boolean);

let command = `cd ${shQuote(projectRoot)} && ${shQuote(python)} -m product_feedback_agent.orchestrator --feedback-file ${shQuote(feedbackFile)} --query ${shQuote(analysisQuery)}`;
for (const file of contextFiles) {
  command += ` --context-file ${shQuote(file)}`;
}

return [{ json: { command } }];

const item = $input.first().json;
if (item.exitCode !== 0) {
  throw new Error(`Analysis failed (exit code ${item.exitCode}): ${item.stderr}`);
}
const orchestrationResult = JSON.parse(item.stdout);
return [{ json: { orchestrationResult } }];

const result = $json.orchestrationResult;

const sections = result.opportunities.map((opportunity) => {
  const validated = result.validation_result.opportunities.find(
    (v) => v.opportunity_id === opportunity.opportunity_id
  );
  const evidenceCount = validated ? validated.evidence_count : 'n/a';
  const score = validated ? validated.score.total.toFixed(2) : 'n/a';
  const unresolved = validated ? validated.issues.length : 0;
  return [
    `### ${opportunity.opportunity_id}: ${opportunity.title}`,
    `Score: ${score} | Evidence count: ${evidenceCount} | Unresolved deterministic issues: ${unresolved}`,
    opportunity.problem_statement,
  ].join('\n');
});

const summaryMarkdown = [
  `**Run/cache reference:** \`${result.cache_key}\``,
  `**Critic status:** ${result.critic_output.status} | **Revised:** ${result.revised} | **Model requests:** ${result.model_request_count}`,
  `**Total unresolved deterministic issues:** ${result.unresolved_issue_count}`,
  '',
  sections.join('\n\n'),
].join('\n');

return [{ json: { orchestrationResult: result, summaryMarkdown } }];

const projectRoot = $env.PFA_PROJECT_ROOT;
const python = $env.PFA_PYTHON || 'python';
if (!projectRoot) {
  throw new Error('PFA_PROJECT_ROOT environment variable is not set on the n8n host. See docs/n8n-setup.md.');
}

function shQuote(value) {
  return `'${String(value).replace(/'/g, "'\\''")}'`;
}

const orchestrationResult = $('Parse Orchestration Result').first().json.orchestrationResult;
const opportunityId = $json['opportunity_id to act on (leave blank to reject)'];
const repo = $json['Target GitHub repo (owner/name)'];
const tempFile = `${projectRoot}/data/local/n8n-run-${$execution.id}.json`;
const resultJson = JSON.stringify(orchestrationResult);

const writeCommand = `cat > ${shQuote(tempFile)} <<'PFA_EOF'\n${resultJson}\nPFA_EOF`;
const runCommand = `cd ${shQuote(projectRoot)} && ${shQuote(python)} -m product_feedback_agent.github_action --result-file ${shQuote(tempFile)} --opportunity-id ${shQuote(opportunityId)} --repo ${shQuote(repo)} --allowed-repo ${shQuote(repo)} --approved --no-dry-run`;

return [{ json: { command: `${writeCommand}\n${runCommand}` } }];

const item = $input.first().json;
if (item.exitCode !== 0) {
  throw new Error(`GitHub action failed (exit code ${item.exitCode}): ${item.stderr}`);
}
const actionResult = JSON.parse(item.stdout);
return [{ json: { actionResult } }];
